<?php elseif($clave==='inventario'): ?><p>Stock en la instantánea: <?= (int)$f['stock'] ?> · Unidades estimadas en 7 días: <?= e($f['demanda_7d']) ?></p><p class="<?= $f['alerta']?'control-warning':'' ?>"><?= $f['alerta']?'Riesgo proyectado: revisar reposición de '.$f['reposicion'].' unidades.':'Sin insuficiencia proyectada para siete días.' ?></p><p>Agotamiento estimado: <?= e($f['fecha']??'No estimado en 30 días') ?> · MAE: <?= e($f['mae']) ?> unidades/día.</p>
