<?php else: ?><p>Actual: <?= e($categorias[$f['actual']]??$f['actual']) ?> · Propuesta: <strong><?= e($categorias[$f['propuesta']]??$f['propuesta']) ?></strong></p><p>Puntuación del modelo: <?= e($f['puntuacion']) ?>. <?= $f['evaluacion']?'Producto reservado para evaluación.':'Producto del conjunto de entrenamiento.' ?></p><?php if($f['actual']!==$f['propuesta']): ?><form method="post" class="negocio-confirmar"><?= csrf_campo() ?><input type="hidden" name="producto" value="<?= (int)$f['id'] ?>"><input type="hidden" name="informe" value="<?= e($r['datos_id']) ?>"><label><input type="checkbox" required> Revisé y acepto cambiar la categoría</label><button class="btn-action">Confirmar categoría propuesta</button></form><?php else: ?><p>La propuesta coincide con la categoría actual.</p><?php endif; ?><?php endif; ?>
